// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.17;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/KARMA.sol";

contract KARMASupplyTest is Test {
    KARMA token;
    address owner = makeAddr("owner");

    // Mock addresses for Uniswap
    address constant ROUTER = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
    address mockFactory = address(0x1234);
    address mockWETH = address(0x5678);
    address mockPair = address(0xabcd);

    function setUp() public {
        // Set chain ID for router selection
        vm.chainId(1);

        // Precompute token address
        uint256 nonce = vm.getNonce(owner);
        address tokenAddress = vm.computeCreateAddress(owner, nonce);

        // Mock router calls
        vm.mockCall(
            ROUTER,
            abi.encodeWithSignature("factory()"),
            abi.encode(mockFactory)
        );
        vm.mockCall(
            ROUTER,
            abi.encodeWithSignature("WETH()"),
            abi.encode(mockWETH)
        );
        vm.mockCall(
            mockFactory,
            abi.encodeWithSignature(
                "createPair(address,address)", 
                tokenAddress, 
                mockWETH
            ),
            abi.encode(mockPair)
        );

        // Deploy token
        vm.startPrank(owner);
        token = new KARMA();
        token.enableTrading();
        vm.stopPrank();
    }

    function test_TotalSupplyDivergenceAfterBurn() public {
        // Configure fees to include burn fee
        vm.startPrank(owner);
        token.excludeFromFees(owner, false);
        token.setBuyFeePercentages(0, 0, 0, 100); // Burn fee only = 1%
        token.setSellFeePercentages(0, 0, 0, 100);
        vm.stopPrank();

        // Calculate transfer amount (50% of owner's balance)
        uint256 ownerBalance = token.balanceOf(owner);
        uint256 transferAmount = ownerBalance / 2;

        // Perform transfer
        vm.prank(owner);
        token.transfer(mockPair, transferAmount);

        // Get balances
        uint256 pairBalance = token.balanceOf(mockPair);
        uint256 deadBalance = token.balanceOf(address(0xdead));
        uint256 ownerRemaining = token.balanceOf(owner);
        uint256 tokenBalance = token.balanceOf(address(token));

        // Calculate balance sum and total supply
        uint256 balanceSum = pairBalance + deadBalance + tokenBalance + ownerRemaining;
        uint256 currentSupply = token.totalSupply();

        // Verify the discrepancy
        assertLt(
            currentSupply,
            balanceSum,
            "Total supply is less than sum of balances"
        );

        // Additional check: calculate expected burn amount
        uint256 feePercentage = 100; // 100 basis points = 1%
        uint256 expectedBurnAmount = (transferAmount * feePercentage) / 1000;
        uint256 expectedBalanceSum = ownerBalance - expectedBurnAmount;

        assertApproxEqAbs(
            balanceSum - currentSupply,
            expectedBurnAmount,
            1e16, // Allow small rounding difference
            "Supply discrepancy matches expected burn amount"
        );
    }
}
